import pandas as pd


def _sig_part(x):
    if pd.isna(x):
        return ''
    return str(x).rstrip()


def _sig(city, tier):
    return _sig_part(city) + '|' + _sig_part(tier)


def run(inputs: dict) -> dict:
    dim = inputs['DIM_MEMBER'].copy()
    stg = inputs['STG_MEMBER'].copy()

    dim = dim.reset_index(drop=True)

    new_rows = []

    for _, s in stg.iterrows():
        member_id = s['member_id']
        mask = (dim['member_id'] == member_id) & (dim['is_current'] == 1)
        idxs = dim.index[mask]

        if len(idxs) == 0:
            new_rows.append({
                'member_id': member_id,
                'city': s['city'],
                'tier': s['tier'],
                'eff_start_date': s['update_date'],
                'eff_end_date': pd.NaT,
                'is_current': 1
            })
        else:
            idx = idxs[0]
            c_city = dim.at[idx, 'city']
            c_tier = dim.at[idx, 'tier']

            if _sig(s['city'], s['tier']) != _sig(c_city, c_tier):
                dim.at[idx, 'eff_end_date'] = s['update_date']
                dim.at[idx, 'is_current'] = 0

                new_rows.append({
                    'member_id': member_id,
                    'city': s['city'],
                    'tier': s['tier'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': pd.NaT,
                    'is_current': 1
                })
            # else: unchanged, no-op

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=dim.columns)
        dim = pd.concat([dim, new_df], ignore_index=True)

    dim = dim[['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']]

    return {'dim_member_out': dim}
